import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M14 8A6 6 0 1 1 2 8a6 6 0 0 1 12 0M9 4H7v2h2zm0 3H6v1h1v3H6v1h4v-1H9z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M17 10a7.001 7.001 0 0 1-11.95 4.95A7 7 0 1 1 17 10m-6-5H9v2h2zm0 3H8v1h1v5H8v1h4v-1h-1z"] as readonly string[];

export const SmallInfoSignIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="small-info-sign" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
SmallInfoSignIcon.displayName = `Blueprint6.Icon.SmallInfoSignIcon`;

/**
 * @deprecated Use {@link SmallInfoSignIcon} instead.
 */
export const SmallInfoSign: typeof SmallInfoSignIcon = SmallInfoSignIcon;

export default SmallInfoSignIcon;
